import '../../../../../../Core/Models/product_details_model.dart';class ProductDetailsEntities extends ProductDetailsModel {  ProductDetailsEntities({    required super.name,    required super.description,    required super.additionalInfo,    required super.price,    required super.discountPrice,    required super.dimensions,    required super.status,    required super.quantity,    required super.images,    required super.colors,    required super.sizes,    required super.materials,    required super.reviews,    required super.id,    required super.primaryImage,    required super.model3D,  }) : super(          // slug: "",          createdAt: null,          updatedAt: null,          // featured: 0,          // popular: 0,          // categoryId: 0,        );  factory ProductDetailsEntities.fromProduct(ProductDetailsModel product) {    return ProductDetailsEntities(      id: product.id,      name: product.name,      description: product.description,      additionalInfo: product.additionalInfo,      price: product.price,      discountPrice: product.discountPrice,      dimensions: product.dimensions,      status: product.status,      quantity: product.quantity,      images: product.images,      colors: product.colors,      sizes: product.sizes,      materials: product.materials,      reviews: product.reviews,      primaryImage: product.primaryImage,      model3D: product.model3D,    );  }  @override  Map<String, dynamic> toJson() {    return {      'id': id,      'name': name,      // 'slug': slug,      // 'category_id': categoryId,      'description': description,      'additional_info': additionalInfo,      'price': price,      'discount_price': discountPrice,      'dimensions': dimensions,      'status': status,      'quantity': quantity,      'images': images.map((x) => x.toJson()).toList(),      'colors': colors.map((x) => x.toJson()).toList(),      'sizes': sizes.map((x) => x.toJson()).toList(),      'materials': materials.map((x) => x.toJson()).toList(),      'reviews': reviews.map((x) => x).toList(),      'primary_image': primaryImage?.toJson(),      'model_3d_url': model3D,    };  }  // Keep toMap for backward compatibility if needed  Map<String, dynamic> toMap() {    return toJson();  }}